// Video-to-ASCII frame extraction using requestVideoFrameCallback
// Source: adapted from nexu-io/open-design + workadventure + MDN

function createVideoToAsciiPipeline(
  video: HTMLVideoElement,
  offscreenCanvas: HTMLCanvasElement,
  onFrame: (imageData: ImageData, frameIndex: number) => void,
  options: { targetWidth: number; targetHeight: number }
): { stop: () => void; isRunning: () => boolean } {
  const ctx = offscreenCanvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Canvas 2D context unavailable');

  let running = true;
  let frameIndex = 0;
  let rafId: number | null = null;
  let rvfcHandle: number | null = null;

  offscreenCanvas.width = options.targetWidth;
  offscreenCanvas.height = options.targetHeight;

  const supportsRVFC = typeof HTMLVideoElement !== 'undefined' &&
    'requestVideoFrameCallback' in HTMLVideoElement.prototype;

  function captureFrame() {
    if (!running || video.paused || video.ended) return;

    // Draw current video frame to offscreen canvas
    ctx.drawImage(video, 0, 0, offscreenCanvas.width, offscreenCanvas.height);
    // Extract pixel data for ASCII conversion
    const imageData = ctx.getImageData(0, 0, offscreenCanvas.width, offscreenCanvas.height);
    frameIndex++;
    onFrame(imageData, frameIndex);
  }

  function tickRVFC(_now: DOMHighResTimeStamp, _metadata: VideoFrameCallbackMetadata) {
    if (!running) return;
    captureFrame();
    rvfcHandle = video.requestVideoFrameCallback!(tickRVFC);
  }

  function tickRAF() {
    if (!running || video.paused || video.ended) return;
    captureFrame();
    rafId = requestAnimationFrame(tickRAF);
  }

  // Start: prefer rVFC for frame-accurate capture, fallback to RAF
  if (supportsRVFC && typeof video.requestVideoFrameCallback === 'function') {
    rvfcHandle = video.requestVideoFrameCallback(tickRVFC);
  } else {
    rafId = requestAnimationFrame(tickRAF);
  }

  return {
    stop() {
      running = false;
      if (rvfcHandle !== null && video.cancelVideoFrameCallback) {
        video.cancelVideoFrameCallback(rvfcHandle);
      }
      if (rafId !== null) {
        cancelAnimationFrame(rafId);
      }
    },
    isRunning() { return running; },
  };
}

// Image-to-ASCII conversion via Canvas extraction
// Source: adapted from google/adk-samples + MDN

function imageToAsciiData(
  img: HTMLImageElement,
  targetWidth: number,
  targetHeight: number
): ImageData {
  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('Canvas 2D context unavailable');

  // Draw scaled image to target dimensions
  ctx.drawImage(img, 0, 0, targetWidth, targetHeight);
  return ctx.getImageData(0, 0, targetWidth, targetHeight);
}

