// Monochrome Loading Spinner — Pure CSS, no libraries
// Source: adapted from turbostarter/loading-ui + clash-verge-rev

import React from 'react';

interface AsciiLoaderProps {
  size?: number;
  label?: string;
}

export const AsciiLoader: React.FC<AsciiLoaderProps> = ({
  size = 24,
  label = 'Loading ASCII engine...',
}) => (
  <div className="flex flex-col items-center justify-center gap-3" role="status" aria-label={label}>
    <div className="relative" style={{ width: size, height: size }}>
      {/* Outer ring */}
      <div
        className="absolute inset-0 rounded-full border-2 border-[#333] border-t-[#fff]"
        style={{ animation: 'ascii-spin 1s linear infinite' }}
      />
      {/* Inner dot */}
      <div
        className="absolute rounded-full bg-[#fff]"
        style={{
          width: size * 0.25,
          height: size * 0.25,
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          animation: 'ascii-pulse 1.5s ease-in-out infinite',
        }}
      />
    </div>
    <span className="text-[11px] font-mono text-[#888] tracking-wide" aria-live="polite">
      {label}
    </span>
    <style>{`
      @keyframes ascii-spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
      }
      @keyframes ascii-pulse {
        0%, 100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
        50% { opacity: 0.3; transform: translate(-50%, -50%) scale(0.6); }
      }
    `}</style>
  </div>
);

