  --bg: #000000;
  --surface: #0a0a0c;
  --surface-elevated: #141416;
  --surface-hover: #1c1c1e;
  --border: #222224;
  --border-focus: #ffffff;

  /* Text hierarchy — pure white scale */
  --text-primary: #ffffff;
  --text-secondary: #a0a0a0;
  --text-muted: #606060;
  --text-accent: #ffffff;

  /* Accent — single blue for interactive elements only */
  --accent: #3b82f6;
  --accent-hover: #2563eb;
  --accent-muted: rgba(59, 130, 246, 0.12);

  /* Status — minimal, desaturated */
  --status-recording: #ef4444;
  --status-success: #22c55e;
  --status-error: #ef4444;

  /* Radii — tighter, more geometric */
  --radius-card: 4px;
  --radius-button: 3px;
  --radius-tag: 2px;

  /* Motion */
  --duration-fast: 120ms;
  --duration-standard: 180ms;
  --duration-emphasis: 300ms;
  --timing: cubic-bezier(0.16, 1, 0.3, 1);

