  color: var(--text-primary);
  font-family: var(--font-sans);
}

// Critical: Video must actually play before frame extraction works
// Common bug: video.load() called but play() never awaited
// Source: workadventure + MDN video processing guide

async function ensureVideoPlaying(video: HTMLVideoElement): Promise<void> {
  if (!video.src && !video.srcObject) {
    throw new Error('Video has no source. Call video.load() first.');
  }

  // Wait for loadeddata if not ready
  if (video.readyState < 2) {
    await new Promise<void>((resolve, reject) => {
      const onLoaded = () => { video.removeEventListener('loadeddata', onLoaded); resolve(); };
      const onError = () => { video.removeEventListener('error', onError); reject(new Error('Video failed to load')); };
      video.addEventListener('loadeddata', onLoaded);
      video.addEventListener('error', onError);
    });
  }

  // Now play — must await for autoplay policy compliance
  try {
    await video.play();
  } catch (err: any) {
    // Tauri webview may block autoplay. Show user gesture requirement.
    throw new Error(`Video playback blocked: ${err.message}. Click play in the app.`);
  }
}

